<?php
function page_heading(string $eyebrow,string $title,string $subtitle='',string $actionHtml=''): void { echo '<div class="page-heading"><div><div class="eyebrow">'.e($eyebrow).'</div><h1>'.e($title).'</h1>'.($subtitle!==''?'<p>'.e($subtitle).'</p>':'').'</div>'.($actionHtml!==''?'<div class="d-flex gap-2 flex-wrap">'.$actionHtml.'</div>':'').'</div>'; }
function stat_card(string $label,string $value,string $icon,string $note=''): string { return '<div class="card stat-card h-100"><div class="d-flex justify-content-between align-items-center"><span class="stat-label">'.e($label).'</span><span class="stat-icon"><i class="bi bi-'.e($icon).'"></i></span></div><div class="stat-value">'.e($value).'</div><div class="stat-note">'.e($note).'</div></div>'; }
function empty_row(int $cols,string $message='No records found yet.'): string { return '<tr><td colspan="'.(int)$cols.'"><div class="empty-state"><i class="bi bi-inbox"></i><span data-i18n-auto>'.e($message).'</span></div></td></tr>'; }
